#include <iostream>
#include <random>
#include <cmath>
#include <vector>
#include <algorithm>
using namespace std;

int main(int argc, char* argv[]) {
    int seed = 1;
    int w = 6, h = 6;
    if (argc > 1) seed = atoi(argv[1]);
    if (argc > 2) w = atoi(argv[2]);
    if (argc > 3) h = atoi(argv[3]);

    mt19937 mt(seed);
    normal_distribution<double> ndist(0.0, 1.0);

    // Generate initial grid
    vector<vector<double>> grid(h, vector<double>(w));
    for (int y = 0; y < h; y++)
        for (int x = 0; x < w; x++)
            grid[y][x] = ndist(mt);

    // Smooth multiple times
    auto smooth = [&](int iters) {
        for (int iter = 0; iter < iters; iter++) {
            vector<vector<double>> new_grid = grid;
            for (int y = 0; y < h; y++) {
                for (int x = 0; x < w; x++) {
                    double sum = 0;
                    int cnt = 0;
                    for (int dy = -1; dy <= 1; dy++) {
                        for (int dx = -1; dx <= 1; dx++) {
                            int ny = (y+dy+h)%h, nx = (x+dx+w)%w;
                            sum += grid[ny][nx];
                            cnt++;
                        }
                    }
                    new_grid[y][x] = sum / cnt;
                }
            }
            grid = new_grid;
        }
    };

    smooth(40);

    // Scale to 0-20 range
    double mn = 1e18, mx = -1e18;
    for (int y = 0; y < h; y++)
        for (int x = 0; x < w; x++) {
            mn = min(mn, grid[y][x]);
            mx = max(mx, grid[y][x]);
        }

    cout << "Smoothed 40 iters, scaled to 0-20:" << endl;
    for (int y = 0; y < h; y++) {
        for (int x = 0; x < w; x++) {
            int val = (int)round((grid[y][x] - mn) / (mx - mn) * 20);
            cout << val << " ";
        }
        cout << endl;
    }

    return 0;
}
