        for (int y = 0; y < h; y++)
            for (int x = 0; x < w; x++) {
                double s = 0; int c = 0;
                for (int dy = -1; dy <= 1; dy++)
                    for (int dx = -1; dx <= 1; dx++) {
                        s += grid[(y+dy+h)%h][(x+dx+w)%w];
                        c++;
                    }
                ng[y][x] = s/c;
