# 
# Let me look at this COMPLETELY differently.
# 
# I remember that in Halite I, the map generation code used COSINE BASIS FUNCTIONS.
# Specifically, it used a weighted sum of cosine waves at different frequencies.
# 
# Actually, let me search for clues in the bot protocol.
# The bot receives production values as part of init.
# These values were in the range 0-20 (approximately).
# 
# And the strength values were in 0-255 range.
# 
# Looking at the values more carefully:
# Seed 1, 4x4: prods = [1,5,3,3, 4,6,6,9, 8,11,7,15, 4,11,7,9]
# 
# What if each production value is computed as:
# p = sum over some "basis functions" evaluated at (x, y) with random amplitudes
# 
# Like: p[y][x] = round( max(0, A[0]*cos(2pi*x/w) + A[1]*cos(2pi*y/h) + A[2]*cos(2pi*(x+y)/w) + ...) )
# 
# But this would be highly regular.
# 
# Looking at the values again:
# The 4x4 map has max production 15 at (3,2).
# The map has NO obvious symmetry for 1-player.
# 
# Actually wait - let me re-examine the coordinate system.
# In the 4x4 map, position (3,2) has prod=15.
# In terms of array access: row y=2, col x=3.
# 
# For the 30x30 map seed 42 1-player, we saw values up to 15 in the upper-left area.
# And the 4x4 map also has highest value (15) in a corner area.
# 
# Let me test: maybe the production values are generated cell by cell using
# a smooth function of the cell coordinates and multiple random "frequencies".
#
# Actually, the most likely algorithm for Halite I based on my memory:
# 
# The production map is generated using:
# 1. For each cell, compute a value based on sum of sine/cosine waves
# 2. The frequencies and amplitudes are randomly generated for each map
# 3. The number of waves is fixed (maybe 5-7)
# 
# This would give smooth but unique patterns for each seed.
# 
# Let me test this hypothesis:

cat > /tmp/test_fourier.cpp << 'EOF'
#include <iostream>
#include <random>
#include <cmath>
#include <vector>
#include <algorithm>
#include <climits>
using namespace std;

const double PI = 3.14159265358979323846;

void fourier_map(int seed, int w, int h, int num_waves, double amp_scale,
                 vector<vector<double>>& grid) {
    mt19937 mt(seed);
    uniform_real_distribution<double> phase_dist(0.0, 2*PI);
    normal_distribution<double> amp_dist(0.0, 1.0);

    grid.assign(h, vector<double>(w, 0.0));

    for (int wave = 0; wave < num_waves; wave++) {
        double fx = (double)(mt() % (w+1)) / w;
        double fy = (double)(mt() % (h+1)) / h;
        double phase = phase_dist(mt);
        double amp = abs(amp_dist(mt));

        for (int y = 0; y < h; y++)
            for (int x = 0; x < w; x++)
                grid[y][x] += amp * cos(2*PI*(fx*x + fy*y) + phase);
    }
}

int main() {
    int w = 4, h = 4;
    vector<int> expected_prods = {1, 5, 3, 3, 4, 6, 6, 9, 8, 11, 7, 15, 4, 11, 7, 9};

    int best_err = INT_MAX;

    for (int num_waves = 3; num_waves <= 15; num_waves++) {
        vector<vector<double>> grid;
        fourier_map(1, w, h, num_waves, 1.0, grid);

        // Scale to 0-15
        double mn = 1e18, mx = -1e18;
        for (auto& row : grid) for (auto v : row) { mn = min(mn,v); mx = max(mx,v); }

        int err = 0;
        for (int y = 0; y < h; y++)
            for (int x = 0; x < w; x++) {
                int v = (int)round((grid[y][x]-mn)/(mx-mn)*15);
                err += abs(v - expected_prods[y*w+x]);
            }

        if (err < best_err) {
            best_err = err;
            cout << "waves=" << num_waves << " err=" << err << endl;
        }
    }

    return 0;
}
