void interp_map(int seed, int w, int h, int base_w, int base_h,
                vector<vector<int>>& result, int max_val) {
    mt19937 mt(seed);
    uniform_real_distribution<double> ud(0.0, 1.0);

    // Generate base grid
    vector<vector<double>> base(base_h, vector<double>(base_w));
    for (int y = 0; y < base_h; y++)
        for (int x = 0; x < base_w; x++)
            base[y][x] = ud(mt);

    // Bilinear interpolation to full size
    result.assign(h, vector<int>(w));
    for (int y = 0; y < h; y++) {
        for (int x = 0; x < w; x++) {
            // Map (x,y) to base coordinates
            double bx = (double)x / w * base_w;
            double by = (double)y / h * base_h;

            int x0 = (int)bx % base_w;
            int y0 = (int)by % base_h;
            int x1 = (x0 + 1) % base_w;
            int y1 = (y0 + 1) % base_h;

            double fx = bx - (int)bx;
            double fy = by - (int)by;

            double v = base[y0][x0] * (1-fx) * (1-fy) +
                      base[y0][x1] * fx * (1-fy) +
                      base[y1][x0] * (1-fx) * fy +
                      base[y1][x1] * fx * fy;

            result[y][x] = (int)round(v * max_val);
        }
    }
