#include <iostream>
#include <random>
#include <cmath>
#include <vector>
#include <algorithm>
using namespace std;

// Control-point based map generation
void cp_map(int seed, int w, int h, int num_cp, double sigma, int max_val,
            vector<vector<int>>& result) {
    mt19937 mt(seed);
    uniform_real_distribution<double> udx(0.0, w);
    uniform_real_distribution<double> udy(0.0, h);
    uniform_int_distribution<int> uid_val(0, max_val);

    vector<tuple<double,double,int>> cps; // x, y, value
    for (int i = 0; i < num_cp; i++) {
        cps.emplace_back(udx(mt), udy(mt), uid_val(mt));
    }

    result.assign(h, vector<int>(w));
    for (int y = 0; y < h; y++) {
        for (int x = 0; x < w; x++) {
            double sum_w = 0, sum_wv = 0;
            for (auto& [cx, cy, cv] : cps) {
                double dx = min(abs(x+0.5-cx), w-abs(x+0.5-cx));
                double dy = min(abs(y+0.5-cy), h-abs(y+0.5-cy));
                double dist2 = dx*dx + dy*dy;
                double w_val = exp(-dist2 / (2*sigma*sigma));
                sum_w += w_val;
                sum_wv += w_val * cv;
            }
            result[y][x] = (sum_w > 0) ? (int)round(sum_wv / sum_w) : 0;
        }
    }
}

int main() {
    vector<int> exp4 = {1, 5, 3, 3, 4, 6, 6, 9, 8, 11, 7, 15, 4, 11, 7, 9};

    int best_err = 1000;

    for (int ncp : {1, 2, 3, 4, 5, 8, 10, 16}) {
        for (int sig10 : {5, 10, 15, 20, 30, 50}) {
            for (int mv : {15, 16, 20}) {
                vector<vector<int>> result;
                cp_map(1, 4, 4, ncp, sig10/10.0, mv, result);
                int err = 0;
                for (int y = 0; y < 4; y++)
                    for (int x = 0; x < 4; x++)
                        err += abs(result[y][x] - exp4[y*4+x]);
                if (err < best_err) {
                    best_err = err;
                    if (err < 10) cout << "GOOD: ncp=" << ncp << " sigma=" << sig10/10.0 << " mv=" << mv << " err=" << err << endl;
                }
            }
        }
    }
    cout << "Best error: " << best_err << endl;

    return 0;
}
