#include <iostream>
#include <random>
#include <cmath>
#include <vector>
#include <algorithm>
using namespace std;

void gblur_map(int seed, int w, int h, double sigma_factor, int max_val,
               vector<vector<int>>& result) {
    mt19937 mt(seed);
    normal_distribution<double> nd(0.0, 1.0);

    // Generate initial random grid
    vector<vector<double>> raw(h, vector<double>(w));
    for (int y = 0; y < h; y++)
        for (int x = 0; x < w; x++)
            raw[y][x] = nd(mt);

    // Apply Gaussian blur with sigma = sigma_factor * sqrt(w*h)
    double sigma = sigma_factor * sqrt((double)w*h);
    int radius = (int)ceil(3*sigma);

    // Precompute Gaussian kernel
    vector<vector<double>> kernel(2*radius+1, vector<double>(2*radius+1));
    double sum = 0;
    for (int dy = -radius; dy <= radius; dy++) {
        for (int dx = -radius; dx <= radius; dx++) {
            double v = exp(-(dx*dx+dy*dy)/(2*sigma*sigma));
            kernel[dy+radius][dx+radius] = v;
            sum += v;
        }
    }

    // Apply convolution (toroidal)
    vector<vector<double>> blurred(h, vector<double>(w, 0));
    for (int y = 0; y < h; y++) {
        for (int x = 0; x < w; x++) {
            double s = 0, sw = 0;
            for (int dy = -radius; dy <= radius; dy++) {
                for (int dx = -radius; dx <= radius; dx++) {
                    double k = kernel[dy+radius][dx+radius];
                    s += k * raw[(y+dy+h)%h][(x+dx+w)%w];
                    sw += k;
                }
            }
            blurred[y][x] = s / sw;
        }
    }

    // Scale to 0-max_val
    double mn = blurred[0][0], mx = blurred[0][0];
    for (auto& row : blurred) for (auto v : row) { mn=min(mn,v); mx=max(mx,v); }

    result.assign(h, vector<int>(w));
    for (int y = 0; y < h; y++)
        for (int x = 0; x < w; x++)
            result[y][x] = (mx==mn) ? 0 : (int)round((blurred[y][x]-mn)/(mx-mn)*max_val);
}

