#include <vector>
#include <cmath>
#include <numeric>
using namespace std;

// Hypothesis: generate N random values, scale min/max to 0-15
// Try different N
void test(int seed, int N, int scale, const vector<int>& expected_prods, 
          const vector<int>& expected_strs) {
    mt19937 mt(seed);
    normal_distribution<double> nd(0.0, 1.0);

    vector<double> raw;
    for (int i = 0; i < N; i++) raw.push_back(nd(mt));

    double mn = *min_element(raw.begin(), raw.end());
    double mx = *max_element(raw.begin(), raw.end());

    int err_prod = 0;
    for (int i = 0; i < (int)expected_prods.size(); i++) {
        int v = (mx==mn) ? 0 : (int)round((raw[i]-mn)/(mx-mn)*scale);
        err_prod += abs(v - expected_prods[i]);
    }

    // Check if remaining N values work for strength
    // ...

    if (err_prod == 0) {
        cout << "PERFECT PROD MATCH! seed=" << seed << " N=" << N << " scale=" << scale << endl;
    }
}

int main() {
    // Seed 1, 2x2: prods=[6,12,5,8], strs=[193,189,244,219]
