        for (int i = 0; i < N; i++) raw.push_back(abs(nd(mt)));

        double mn = *min_element(raw.begin(), raw.end());
        double mx = *max_element(raw.begin(), raw.end());

        for (int scale = 10; scale <= 20; scale++) {
            int err = 0;
            for (int i = 0; i < 4; i++) {
                int v = (mx==mn) ? 0 : (int)round((raw[i]-mn)/(mx-mn)*scale);
                err += abs(v - exp_p1[i]);
            }
            if (err == 0) cout << "ABS NORMAL MATCH! N=" << N << " scale=" << scale << endl;
        }
    }

    // What about squared normal?
    for (int N = 4; N <= 50; N++) {
        mt19937 mt(1);
        normal_distribution<double> nd(0.0, 1.0);
        vector<double> raw;
        for (int i = 0; i < N; i++) {
            double v = nd(mt);
            raw.push_back(v*v);
        }

        double mn = *min_element(raw.begin(), raw.end());
        double mx = *max_element(raw.begin(), raw.end());

        for (int scale = 10; scale <= 20; scale++) {
            int err = 0;
            for (int i = 0; i < 4; i++) {
                int v = (mx==mn) ? 0 : (int)round((raw[i]-mn)/(mx-mn)*scale);
                err += abs(v - exp_p1[i]);
