void check_seed1_2x2() {
    vector<int> exp_p = {6, 12, 5, 8};
    vector<int> exp_s = {193, 189, 244, 219};

    // Try many combinations: 
    // Different distributions and skip counts
    for (int mode = 0; mode < 8; mode++) {
        for (int skip = 0; skip <= 20; skip++) {
            for (int N_extra = 0; N_extra <= 16; N_extra++) {
                mt19937 mt(1);
                normal_distribution<double> nd(0.0, 1.0);
                uniform_real_distribution<double> ud(0.0, 1.0);

                // Skip values
                for (int s = 0; s < skip; s++) nd(mt);

                vector<double> raw(4);
                for (int i = 0; i < 4; i++) {
                    switch(mode) {
                        case 0: raw[i] = nd(mt); break;
                        case 1: raw[i] = abs(nd(mt)); break;
                        case 2: raw[i] = nd(mt)*nd(mt); break;
                        case 3: raw[i] = ud(mt); break;
                        case 4: raw[i] = abs(nd(mt)) + abs(nd(mt)); break;
                        case 5: {
                            double v = 0;
                            for (int j = 0; j < N_extra+1; j++) v += abs(nd(mt));
                            raw[i] = v;
                            break;
                        }
                        case 6: raw[i] = (double)(mt() % 16); break;
                        case 7: raw[i] = nd(mt) + nd(mt) + nd(mt); break;
                    }
                }

                double mn = *min_element(raw.begin(), raw.end());
                double mx = *max_element(raw.begin(), raw.end());

                for (int scale = 8; scale <= 20; scale++) {
                    int err = 0;
                    for (int i = 0; i < 4; i++) {
                        int v;
                        if (mx == mn) v = 0;
                        else v = (int)round((raw[i]-mn)/(mx-mn)*scale);
                        err += abs(v - exp_p[i]);
                    }
                    if (err == 0) {
                        cout << "MATCH! mode=" << mode << " skip=" << skip 
                             << " N_extra=" << N_extra << " scale=" << scale << endl;
                    }
                }
            }
        }
    }
}

int main() {
    check_seed1_2x2();
    return 0;
}
