# generate PARAMETERS for a mathematical function, which was then EVALUATED at each cell.
# 
# The specific mathematical function used in Halite I was the SUM OF SINUSOIDAL WAVES:
# 
# For each "frequency component" k:
# amplitude_k = drawn from some distribution (based on RNG)
# frequency_x_k = small integer (1, 2, or 3)
# frequency_y_k = small integer (1, 2, or 3)
# phase_x_k = drawn from uniform [0, 2pi)
# phase_y_k = drawn from uniform [0, 2pi)
# 
# value(x, y) = sum_k amplitude_k * cos(2pi * freq_x_k * x / W + phase_x_k)
#                                 * cos(2pi * freq_y_k * y / H + phase_y_k)
# 
# Then normalized to 0-15 range.
# 
# This would give smooth maps for large W,H and "noisy" maps for small W,H
# (when the period of the wave is comparable to the map size).
# 
# Let me test this with BOTH continuous frequency values (not just integers):

cat > /tmp/test_waves.cpp << 'EOF'
#include <iostream>
#include <random>
#include <cmath>
#include <vector>
#include <algorithm>
#include <climits>
using namespace std;

const double PI = acos(-1.0);

void wave_map(int seed, int w, int h, int N, int max_val,
              vector<vector<int>>& result) {
    mt19937 mt(seed);
    normal_distribution<double> nd(0.0, 1.0);
    uniform_real_distribution<double> phase_dist(0.0, 2*PI);
    uniform_int_distribution<int> freq_dist(1, 5);

    vector<double> Ak(N);
    vector<int> fxk(N), fyk(N);
    vector<double> px(N), py(N);

    for (int k = 0; k < N; k++) {
        Ak[k] = abs(nd(mt));
        fxk[k] = freq_dist(mt);
        fyk[k] = freq_dist(mt);
        px[k] = phase_dist(mt);
        py[k] = phase_dist(mt);
    }

    vector<vector<double>> grid(h, vector<double>(w));
    for (int y = 0; y < h; y++) {
        for (int x = 0; x < w; x++) {
            double v = 0;
            for (int k = 0; k < N; k++) {
                v += Ak[k] * cos(2*PI*fxk[k]*x/w + px[k]) * cos(2*PI*fyk[k]*y/h + py[k]);
            }
            grid[y][x] = v;
        }
    }

    double mn = grid[0][0], mx = grid[0][0];
    for (auto& row : grid) for (double v : row) { mn = min(mn,v); mx = max(mx,v); }

    result.assign(h, vector<int>(w));
    for (int y = 0; y < h; y++)
        for (int x = 0; x < w; x++)
            result[y][x] = (mx==mn) ? 0 : (int)round((grid[y][x]-mn)/(mx-mn)*max_val);
}

int main() {
    vector<int> exp4_s1 = {1, 5, 3, 3, 4, 6, 6, 9, 8, 11, 7, 15, 4, 11, 7, 9};
    vector<int> exp4_s2 = {4, 4, 4, 3, 3, 5, 3, 2, 5, 5, 3, 4, 3, 7, 7, 4};

    int best_err_s1 = INT_MAX;
    int best_N = -1, best_mv = -1;

    for (int N = 1; N <= 20; N++) {
        for (int mv : {13, 14, 15, 19, 20}) {
            vector<vector<int>> r;
            wave_map(1, 4, 4, N, mv, r);
            int err = 0;
            for (int y = 0; y < 4; y++)
                for (int x = 0; x < 4; x++)
                    err += abs(r[y][x] - exp4_s1[y*4+x]);

            if (err < best_err_s1) {
                best_err_s1 = err;
                best_N = N;
                best_mv = mv;
                if (err < 5) {
                    cout << "CLOSE! N=" << N << " mv=" << mv << " err=" << err << endl;
                }
            }
        }
    }

    cout << "Best for seed 1, 4x4: N=" << best_N << " mv=" << best_mv << " err=" << best_err_s1 << endl;

    return 0;
}
EOF
