#include <vector>
#include <algorithm>
using namespace std;

void blob_exact(int seed, int w, int h, int N, double sigma, double A_max, int max_val,
                vector<vector<int>>& result) {
    mt19937 mt(seed);
    uniform_real_distribution<double> udx(0.0, w);
    uniform_real_distribution<double> udy(0.0, h);
    uniform_real_distribution<double> uda(0.0, A_max);

    struct Blob { double x, y, a; };
    vector<Blob> blobs(N);
    for (auto& b : blobs) {
        b.x = udx(mt);
        b.y = udy(mt);
        b.a = uda(mt);
    }

    // Compute grid values
    vector<vector<double>> grid(h, vector<double>(w, 0));
    for (int y = 0; y < h; y++) {
        for (int x = 0; x < w; x++) {
            for (auto& b : blobs) {
                double dx = x - b.x, dy = y - b.y;
                // Toroidal:
                if (dx > w/2) dx -= w; if (dx < -w/2) dx += w;
                if (dy > h/2) dy -= h; if (dy < -h/2) dy += h;
                double d2 = dx*dx + dy*dy;
                grid[y][x] += b.a * exp(-d2 / (2*sigma*sigma));
            }
        }
    }

    double mn = grid[0][0], mx = grid[0][0];
    for (auto& row : grid) for (double v : row) { mn=min(mn,v); mx=max(mx,v); }

    result.assign(h, vector<int>(w));
    for (int y = 0; y < h; y++)
        for (int x = 0; x < w; x++)
            result[y][x] = (mx==mn) ? 0 : (int)round((grid[y][x]-mn)/(mx-mn)*max_val);
