                    if (err1 == 0) {
                        // Check other seeds
                        blob_exact(2, 2, 2, N, sig10/10.0, Amax, mv, r);
                        int err2 = 0;
                        for (int y = 0; y < 2; y++)
                            for (int x = 0; x < 2; x++)
                                err2 += abs(r[y][x] - exp2_s2[y*2+x]);

                        if (err2 == 0) {
                            blob_exact(3, 2, 2, N, sig10/10.0, Amax, mv, r);
                            int err3 = 0;
                            for (int y = 0; y < 2; y++)
                                for (int x = 0; x < 2; x++)
