#include <iostream>
#include <random>
#include <cmath>
#include <vector>
#include <algorithm>
using namespace std;

const double PI = acos(-1.0);

// Classic Perlin noise implementation
double fade(double t) { return t*t*t*(t*(t*6-15)+10); }
double lerp(double a, double b, double t) { return a + t*(b-a); }
double dot2(double gx, double gy, double px, double py) { return gx*px + gy*py; }

class PerlinNoise {
    int w, h;
    vector<vector<double>> gx, gy; // gradients

public:
    PerlinNoise(int w, int h, mt19937& mt) : w(w), h(h), gx(h+1, vector<double>(w+1)), gy(h+1, vector<double>(w+1)) {
        uniform_real_distribution<double> angle_dist(0, 2*PI);
        for (int y = 0; y <= h; y++) {
            for (int x = 0; x <= w; x++) {
                double angle = angle_dist(mt);
                gx[y][x] = cos(angle);
                gy[y][x] = sin(angle);
            }
        }
    }

    double eval(double x, double y) {
        int x0 = (int)x % w, y0 = (int)y % h;
        int x1 = (x0+1) % w, y1 = (y0+1) % h;
        double fx = x - (int)x, fy = y - (int)y;

        double u = fade(fx), v = fade(fy);

        double n00 = dot2(gx[y0][x0], gy[y0][x0], fx, fy);
        double n10 = dot2(gx[y0][x1], gy[y0][x1], fx-1, fy);
        double n01 = dot2(gx[y1][x0], gy[y1][x0], fx, fy-1);
        double n11 = dot2(gx[y1][x1], gy[y1][x1], fx-1, fy-1);

        return lerp(lerp(n00, n10, u), lerp(n01, n11, u), v);
    }
};

void perlin_map(int seed, int w, int h, int grid_size, int max_val,
                vector<vector<int>>& result) {
    mt19937 mt(seed);

    // Create Perlin noise grid
    int gw = (w + grid_size - 1) / grid_size;
    int gh = (h + grid_size - 1) / grid_size;
    PerlinNoise pn(gw, gh, mt);

    vector<vector<double>> grid(h, vector<double>(w));
    for (int y = 0; y < h; y++) {
        for (int x = 0; x < w; x++) {
