#include <iostream>
#include <random>
#include <cmath>
#include <vector>
#include <algorithm>
using namespace std;

void adaptive_blur_map(int seed, int w, int h, double sigma_factor, int max_val,
                       vector<vector<int>>& result) {
    mt19937 mt(seed);
    normal_distribution<double> nd(0.0, 1.0);

    vector<vector<double>> raw(h, vector<double>(w));
    for (int y = 0; y < h; y++)
        for (int x = 0; x < w; x++)
            raw[y][x] = nd(mt);

    double sigma = sigma_factor * sqrt(w*h);
    int radius = min((int)ceil(2*sigma), min(w,h)-1);

    // Gaussian blur
    vector<vector<double>> blurred(h, vector<double>(w, 0));
    double total_weight = 0;
    vector<pair<int,int>> kernel_pts;
    vector<double> kernel_weights;

    for (int dy = -radius; dy <= radius; dy++) {
        for (int dx = -radius; dx <= radius; dx++) {
            double w_val = exp(-0.5*(dx*dx+dy*dy)/(sigma*sigma));
            kernel_pts.emplace_back(dx, dy);
            kernel_weights.push_back(w_val);
            total_weight += w_val;
        }
    }

    for (int y = 0; y < h; y++) {
        for (int x = 0; x < w; x++) {
            double s = 0, sw = 0;
            for (int k = 0; k < (int)kernel_pts.size(); k++) {
                int ny = ((y + kernel_pts[k].second) % h + h) % h;
                int nx = ((x + kernel_pts[k].first) % w + w) % w;
                s += kernel_weights[k] * raw[ny][nx];
                sw += kernel_weights[k];
            }
            blurred[y][x] = s/sw;
        }
    }

    double mn = blurred[0][0], mx = blurred[0][0];
    for (auto& row : blurred) for (double v : row) { mn=min(mn,v); mx=max(mx,v); }

    result.assign(h, vector<int>(w));
    for (int y = 0; y < h; y++)
        for (int x = 0; x < w; x++)
            result[y][x] = (mx==mn) ? 0 : (int)round((blurred[y][x]-mn)/(mx-mn)*max_val);
}

int main() {
    // Test with known values
    vector<int> exp4_s1 = {1, 5, 3, 3, 4, 6, 6, 9, 8, 11, 7, 15, 4, 11, 7, 9};
    vector<int> exp4_s2 = {4, 4, 4, 3, 3, 5, 3, 2, 5, 5, 3, 4, 3, 7, 7, 4};

    int best_err = 1000;

    for (int sf10 = 1; sf10 <= 20; sf10++) {
        for (int mv : {13, 14, 15}) {
            vector<vector<int>> r;
            adaptive_blur_map(1, 4, 4, sf10/100.0, mv, r);
            int err = 0;
            for (int y = 0; y < 4; y++)
                for (int x = 0; x < 4; x++)
                    err += abs(r[y][x] - exp4_s1[y*4+x]);

            if (err < best_err) {
                best_err = err;
                if (err < 10) {
                    cout << "CLOSE! sf=" << sf10/100.0 << " mv=" << mv << " err=" << err << endl;
                    for (auto& row : r) { for (auto v : row) cout << v << " "; cout << endl; }
                }
            }
        }
    }

    cout << "Best err: " << best_err << endl;

    return 0;
}
