            else tile_w = width / 2;
        }

        std::vector<std::vector<double>> field;
        generate_smooth_field(tile_w, tile_h, field);

        // Extend to full map with symmetry
        if (num_players > 1) {
            // Extend field to full map size first
            std::vector<std::vector<double>> full(height, std::vector<double>(width, 0));
            for (int y = 0; y < tile_h; y++)
                for (int x = 0; x < tile_w; x++)
                    full[y][x] = field[y][x];
            apply_symmetry_2d(full);
            field = full;
        }

        // Find min/max
        double mn = field[0][0], mx = field[0][0];
        for (auto& row : field) for (auto v : row) { mn = std::min(mn,v); mx = std::max(mx,v); }

        // Scale to 0-15
        std::vector<std::vector<int>> result(height, std::vector<int>(width));
        for (int y = 0; y < height; y++)
            for (int x = 0; x < width; x++)
                result[y][x] = (mx == mn) ? 0 : (int)round((field[y][x]-mn)/(mx-mn)*15);

        return result;
    }

    std::vector<std::vector<int>> generate_strengths() {
        std::vector<std::vector<double>> field;
        generate_smooth_field(width, height, field);

        if (num_players > 1) {
            apply_symmetry_2d(field);
        }

        double mn = field[0][0], mx = field[0][0];
        for (auto& row : field) for (auto v : row) { mn = std::min(mn,v); mx = std::max(mx,v); }

        std::vector<std::vector<int>> result(height, std::vector<int>(width));
        for (int y = 0; y < height; y++)
            for (int x = 0; x < width; x++)
                result[y][x] = (mx == mn) ? 0 : (int)round((field[y][x]-mn)/(mx-mn)*255);

        return result;
    }

    // Get starting position for player p (1-indexed) in n_players game
    std::pair<int,int> get_start_pos(int p) {
        if (num_players == 1) {
            return {width/2, height/2};
        }

        // For 2 players with different symmetry types:
        // Base starting position depends on symmetry type
        int p1_x, p1_y;
        if (sym_type == 0) { // vert flip: vertical axis symmetry
            p1_x = width/2;
            p1_y = height/(2*num_players);
        } else if (sym_type == 1) { // horiz flip
            p1_x = width/(2*num_players);
            p1_y = height/2;
        } else if (sym_type == 2) { // half-y+x-flip
            p1_x = width/(2*num_players);
            p1_y = height/2;
        } else { // half-x+y-flip
            p1_x = width/2;
            p1_y = height/(2*num_players);
        }

        // Place players by symmetry
        if (p == 1) return {p1_x, p1_y};

        // Player 2 is symmetric to player 1
        if (sym_type == 0) {
            return {p1_x, height-1-p1_y};
        } else if (sym_type == 1) {
            return {width-1-p1_x, p1_y};
        } else if (sym_type == 2) {
            return {width-1-p1_x, (p1_y + height/2) % height};
        } else {
            return {(p1_x + width/2) % width, height-1-p1_y};
        }
    }

    GameState generate() {
        GameState state;
        state.width = width;
        state.height = height;

        auto prods = generate_productions();
        auto strs = generate_strengths();

        state.productions = prods;
        state.grid.assign(height, std::vector<Cell>(width, {0, 0}));

        // Set initial strengths
