        // Place players
        for (int p = 1; p <= num_players; p++) {
            auto [px, py] = get_start_pos(p);
            state.grid[py][px].owner = p;
        }

        return state;
    }
};

// Compute state string for bot
std::string encode_state(const GameState& state) {
    // Run-length encode owners
    std::vector<std::pair<int,int>> runs;
    int cur_owner = state.grid[0][0].owner;
    int count = 1;

    for (int y = 0; y < state.height; y++) {
        for (int x = (y == 0 ? 1 : 0); x < state.width; x++) {
            int o = state.grid[y][x].owner;
            if (o == cur_owner) {
                count++;
            } else {
                runs.emplace_back(count, cur_owner);
                cur_owner = o;
                count = 1;
            }
        }
    }
    runs.emplace_back(count, cur_owner);

    std::ostringstream oss;
    for (auto& r : runs) {
        oss << r.first << ' ' << r.second << ' ';
    }
    for (int y = 0; y < state.height; y++) {
        for (int x = 0; x < state.width; x++) {
            oss << state.grid[y][x].strength;
            if (y < state.height-1 || x < state.width-1) oss << ' ';
        }
    }
    return oss.str();
}

std::string encode_productions(const GameState& state) {
    std::ostringstream oss;
    for (int y = 0; y < state.height; y++) {
        for (int x = 0; x < state.width; x++) {
            oss << state.productions[y][x];
            if (y < state.height-1 || x < state.width-1) oss << ' ';
        }
    }
    return oss.str();
}

// Bot management
struct Bot {
    int player_id;
    std::string cmd;
    std::string name;

    pid_t pid;
    int stdin_fd;   // write to bot
    int stdout_fd;  // read from bot
    int stderr_fd;  // read from bot's stderr

    bool alive;
    bool timed_out;
    bool errored;

    std::string log_buffer;
    std::string last_response;

    Bot(int id, const std::string& c) : 
        player_id(id), cmd(c), pid(-1), stdin_fd(-1), stdout_fd(-1), stderr_fd(-1),
        alive(false), timed_out(false), errored(false) {}

    bool start() {
        int stdin_pipe[2], stdout_pipe[2], stderr_pipe[2];
        if (pipe(stdin_pipe) < 0 || pipe(stdout_pipe) < 0 || pipe(stderr_pipe) < 0) {
            return false;
        }

        pid = fork();
        if (pid < 0) return false;

        if (pid == 0) {
            // Child process
            close(stdin_pipe[1]);
            close(stdout_pipe[0]);
            close(stderr_pipe[0]);

            dup2(stdin_pipe[0], STDIN_FILENO);
            dup2(stdout_pipe[1], STDOUT_FILENO);
            dup2(stderr_pipe[1], STDERR_FILENO);

            close(stdin_pipe[0]);
            close(stdout_pipe[1]);
            close(stderr_pipe[1]);

            execl("/bin/sh", "sh", "-c", cmd.c_str(), NULL);
            _exit(1);
        }

        close(stdin_pipe[0]);
        close(stdout_pipe[1]);
        close(stderr_pipe[1]);

        stdin_fd = stdin_pipe[1];
        stdout_fd = stdout_pipe[0];
        stderr_fd = stderr_pipe[0];

        // Set stdout and stderr to non-blocking
        fcntl(stdout_fd, F_SETFL, O_NONBLOCK);
        fcntl(stderr_fd, F_SETFL, O_NONBLOCK);

        alive = true;
        return true;
    }

    void write_to_bot(const std::string& s) {
        write(stdin_fd, s.c_str(), s.size());
    }

    // Read a line from bot's stdout with timeout
    // Returns: empty string if timeout, otherwise the line
    std::string read_line(int timeout_ms, bool ignore_timeout = false) {
        std::string line;
        auto start = std::chrono::steady_clock::now();

        while (true) {
            // Try to read a character
            char c;
            ssize_t n = read(stdout_fd, &c, 1);
            if (n > 0) {
                if (c == '\n') {
                    return line;
                }
                line += c;
            } else if (n == 0) {
                // EOF
                errored = true;
                return "";
            } else {
                // EAGAIN - would block
                if (!ignore_timeout) {
                    auto elapsed = std::chrono::duration_cast<std::chrono::milliseconds>(
                        std::chrono::steady_clock::now() - start).count();
                    if (elapsed > timeout_ms) {
                        timed_out = true;
                        errored = true;
                        return "";
                    }
                }
                // Poll for data
                struct pollfd pfd;
                pfd.fd = stdout_fd;
                pfd.events = POLLIN;
                int wait_ms = ignore_timeout ? 100 : std::max(1L, (long)(timeout_ms - 
                    std::chrono::duration_cast<std::chrono::milliseconds>(
                        std::chrono::steady_clock::now() - start).count()));
                int ret = poll(&pfd, 1, wait_ms);
                if (ret <= 0 && !ignore_timeout) {
                    timed_out = true;
                    errored = true;
                    return "";
                }
            }
        }
    }

    // Read available stderr without blocking
    void drain_stderr() {
        char buf[1024];
        ssize_t n;
        while ((n = read(stderr_fd, buf, sizeof(buf)-1)) > 0) {
            buf[n] = 0;
            log_buffer += buf;
        }
    }

    void kill_bot() {
        if (pid > 0) {
            kill(pid, SIGKILL);
            int status;
            waitpid(pid, &status, 0);
            pid = -1;
        }
        if (stdin_fd >= 0) { close(stdin_fd); stdin_fd = -1; }
        if (stdout_fd >= 0) { close(stdout_fd); stdout_fd = -1; }
        if (stderr_fd >= 0) { close(stderr_fd); stderr_fd = -1; }
        alive = false;
    }

    ~Bot() {
        kill_bot();
    }
};

// Game execution
