        TCLAP::SwitchArg overrideArg("o", "override", "Overrides player-sent names using cmd args.", false);
        TCLAP::SwitchArg quietArg("q", "quiet", "Runs game in quiet mode.", false);
        TCLAP::UnlabeledMultiArg<std::string> botCmds("bots", "Start commands for bots.", false, "Array of strings");

        cmd.add(replayDirArg);
        cmd.add(seedArg);
        cmd.add(dimArg);
