        cmd.parse(argc, argv);

        std::vector<std::string> commands = botCmds.getValue();
        int n_bots = commands.size();

        // Handle n_players
        int n_players_arg = nplayersArg.getValue();
        if (n_players_arg > 1 && n_bots > 1) {
