        }

        // For n_players arg with 1 bot: use n_players for map generation
        int effective_players = n_bots > 0 ? n_bots : 1;
        if (n_bots == 1 && n_players_arg > 0) {
            effective_players = n_players_arg;
        }

        // Determine dimensions
        int width = 30, height = 30; // default
        if (!dimArg.getValue().empty()) {
            std::istringstream iss(dimArg.getValue());
            iss >> width >> height;
        } else {
            // Default depends on num_players
            // ... use some formula
        }

        // Adjust dimensions for num players
        auto [aw, ah] = adjust_dimensions(width, height, effective_players);
        width = aw;
        height = ah;

        if (n_bots == 0) {
            std::cerr << "No bots specified." << std::endl;
            return 1;
        }

        // Create and run game
        Game game;
        game.seed = seedArg.getValue();
