        if (num_players > 1) {
            // Extend field to full map size first
            std::vector<std::vector<double>> full(height, std::vector<double>(width, 0));
            for (int y = 0; y < tile_h; y++)
                for (int x = 0; x < tile_w; x++)
                    full[y][x] = field[y][x];
            apply_symmetry_2d(full);
            field = full;
        }

        // Find min/max
        double mn = field[0][0], mx = field[0][0];
        for (auto& row : field) for (auto v : row) { mn = std::min(mn,v); mx = std::max(mx,v); }

        // Scale to 0-15
        std::vector<std::vector<int>> result(height, std::vector<int>(width));
        for (int y = 0; y < height; y++)
            for (int x = 0; x < width; x++)
                result[y][x] = (mx == mn) ? 0 : (int)round((field[y][x]-mn)/(mx-mn)*15);

        return result;
    }

    std::vector<std::vector<int>> generate_strengths() {
        std::vector<std::vector<double>> field;
        generate_smooth_field(width, height, field);

        if (num_players > 1) {
            apply_symmetry_2d(field);
        }

        double mn = field[0][0], mx = field[0][0];
        for (auto& row : field) for (auto v : row) { mn = std::min(mn,v); mx = std::max(mx,v); }

        std::vector<std::vector<int>> result(height, std::vector<int>(width));
        for (int y = 0; y < height; y++)
            for (int x = 0; x < width; x++)
                result[y][x] = (mx == mn) ? 0 : (int)round((field[y][x]-mn)/(mx-mn)*255);

        return result;
    }

    // Get starting position for player p (1-indexed) in n_players game
    std::pair<int,int> get_start_pos(int p) {
        if (num_players == 1) {
            return {width/2, height/2};
        }

        // For 2 players with different symmetry types:
        // Base starting position depends on symmetry type
        int p1_x, p1_y;
        if (sym_type == 0) { // vert flip: vertical axis symmetry
            p1_x = width/2;
            p1_y = height/(2*num_players);
        } else if (sym_type == 1) { // horiz flip
            p1_x = width/(2*num_players);
            p1_y = height/2;
        } else if (sym_type == 2) { // half-y+x-flip
            p1_x = width/(2*num_players);
            p1_y = height/2;
        } else { // half-x+y-flip
            p1_x = width/2;
            p1_y = height/(2*num_players);
        }

        // Place players by symmetry
        if (p == 1) return {p1_x, p1_y};

        // Player 2 is symmetric to player 1
        if (sym_type == 0) {
            return {p1_x, height-1-p1_y};
        } else if (sym_type == 1) {
            return {width-1-p1_x, p1_y};
        } else if (sym_type == 2) {
            return {width-1-p1_x, (p1_y + height/2) % height};
        } else {
            return {(p1_x + width/2) % width, height-1-p1_y};
        }
    }

    GameState generate() {
        GameState state;
        state.width = width;
        state.height = height;

        auto prods = generate_productions();
        auto strs = generate_strengths();

        state.productions = prods;
        state.grid.assign(height, std::vector<Cell>(width, {0, 0}));

        // Set initial strengths
        for (int y = 0; y < height; y++)
            for (int x = 0; x < width; x++)
                state.grid[y][x].strength = strs[y][x];

        // Place players
        for (int p = 1; p <= num_players; p++) {
            auto [px, py] = get_start_pos(p);
            state.grid[py][px].owner = p;
        }

        return state;
    }
};

// Compute state string for bot
std::string encode_state(const GameState& state) {
    // Run-length encode owners
    std::vector<std::pair<int,int>> runs;
    int cur_owner = state.grid[0][0].owner;
    int count = 1;

    for (int y = 0; y < state.height; y++) {
        for (int x = (y == 0 ? 1 : 0); x < state.width; x++) {
            int o = state.grid[y][x].owner;
            if (o == cur_owner) {
                count++;
            } else {
                runs.emplace_back(count, cur_owner);
                cur_owner = o;
                count = 1;
            }
        }
    }
    runs.emplace_back(count, cur_owner);

    std::ostringstream oss;
    for (auto& r : runs) {
        oss << r.first << ' ' << r.second << ' ';
    }
    for (int y = 0; y < state.height; y++) {
        for (int x = 0; x < state.width; x++) {
            oss << state.grid[y][x].strength;
            if (y < state.height-1 || x < state.width-1) oss << ' ';
        }
    }
    return oss.str();
}

std::string encode_productions(const GameState& state) {
    std::ostringstream oss;
    for (int y = 0; y < state.height; y++) {
        for (int x = 0; x < state.width; x++) {
            oss << state.productions[y][x];
            if (y < state.height-1 || x < state.width-1) oss << ' ';
        }
    }
    return oss.str();
}

// Bot management
struct Bot {
    int player_id;
    std::string cmd;
    std::string name;

    pid_t pid;
    int stdin_fd;   // write to bot
    int stdout_fd;  // read from bot
    int stderr_fd;  // read from bot's stderr

    bool alive;
    bool timed_out;
    bool errored;

    std::string log_buffer;
    std::string last_response;

    Bot(int id, const std::string& c) : 
        player_id(id), cmd(c), pid(-1), stdin_fd(-1), stdout_fd(-1), stderr_fd(-1),
        alive(false), timed_out(false), errored(false) {}

    bool start() {
        int stdin_pipe[2], stdout_pipe[2], stderr_pipe[2];
        if (pipe(stdin_pipe) < 0 || pipe(stdout_pipe) < 0 || pipe(stderr_pipe) < 0) {
            return false;
        }

        pid = fork();
        if (pid < 0) return false;

        if (pid == 0) {
            // Child process
            close(stdin_pipe[1]);
            close(stdout_pipe[0]);
            close(stderr_pipe[0]);

            dup2(stdin_pipe[0], STDIN_FILENO);
            dup2(stdout_pipe[1], STDOUT_FILENO);
            dup2(stderr_pipe[1], STDERR_FILENO);

            close(stdin_pipe[0]);
            close(stdout_pipe[1]);
            close(stderr_pipe[1]);

            execl("/bin/sh", "sh", "-c", cmd.c_str(), NULL);
            _exit(1);
        }

        close(stdin_pipe[0]);
        close(stdout_pipe[1]);
        close(stderr_pipe[1]);

        stdin_fd = stdin_pipe[1];
        stdout_fd = stdout_pipe[0];
        stderr_fd = stderr_pipe[0];

        // Set stdout and stderr to non-blocking
        fcntl(stdout_fd, F_SETFL, O_NONBLOCK);
        fcntl(stderr_fd, F_SETFL, O_NONBLOCK);

        alive = true;
        return true;
    }

    void write_to_bot(const std::string& s) {
        write(stdin_fd, s.c_str(), s.size());
    }

    // Read a line from bot's stdout with timeout
    // Returns: empty string if timeout, otherwise the line
    std::string read_line(int timeout_ms, bool ignore_timeout = false) {
        std::string line;
        auto start = std::chrono::steady_clock::now();

        while (true) {
            // Try to read a character
            char c;
            ssize_t n = read(stdout_fd, &c, 1);
            if (n > 0) {
                if (c == '\n') {
                    return line;
                }
                line += c;
            } else if (n == 0) {
                // EOF
                errored = true;
                return "";
            } else {
                // EAGAIN - would block
                if (!ignore_timeout) {
                    auto elapsed = std::chrono::duration_cast<std::chrono::milliseconds>(
                        std::chrono::steady_clock::now() - start).count();
                    if (elapsed > timeout_ms) {
                        timed_out = true;
                        errored = true;
                        return "";
                    }
                }
                // Poll for data
                struct pollfd pfd;
                pfd.fd = stdout_fd;
                pfd.events = POLLIN;
                int wait_ms = ignore_timeout ? 100 : std::max(1L, (long)(timeout_ms - 
                    std::chrono::duration_cast<std::chrono::milliseconds>(
                        std::chrono::steady_clock::now() - start).count()));
                int ret = poll(&pfd, 1, wait_ms);
                if (ret <= 0 && !ignore_timeout) {
                    timed_out = true;
                    errored = true;
                    return "";
                }
            }
        }
    }

    // Read available stderr without blocking
    void drain_stderr() {
        char buf[1024];
        ssize_t n;
        while ((n = read(stderr_fd, buf, sizeof(buf)-1)) > 0) {
            buf[n] = 0;
            log_buffer += buf;
        }
    }

    void kill_bot() {
        if (pid > 0) {
            kill(pid, SIGKILL);
            int status;
            waitpid(pid, &status, 0);
            pid = -1;
        }
        if (stdin_fd >= 0) { close(stdin_fd); stdin_fd = -1; }
        if (stdout_fd >= 0) { close(stdout_fd); stdout_fd = -1; }
        if (stderr_fd >= 0) { close(stderr_fd); stderr_fd = -1; }
        alive = false;
    }

    ~Bot() {
        kill_bot();
    }
};

// Game execution
struct Game {
    int seed;
    int num_players;
    int width, height;
    int max_turns;
    bool replay;
    bool ignore_timeout;
    bool quiet;
    bool override_names;
    std::string replay_dir;

    GameState state;
    std::vector<std::unique_ptr<Bot>> bots;

    // Stats
    std::vector<int> last_alive_frame;
    std::vector<int> ranks;

    // Replay data
    std::vector<std::vector<std::vector<std::pair<int,int>>>> frames; // [frame][y][x] = {owner, str}
    std::vector<std::vector<std::vector<int>>> all_moves; // [frame][y][x] = direction

    int compute_max_turns(int w, int h) {
        return (int)(10 * sqrt(w * h));
    }

    // Compute player starting positions (symmetric)
    void init_game() {
        // Generate map
        MapGen gen(width, height, num_players, seed);
        state = gen.generate();
    }

    // Send init data to all bots
    void send_init(int timeout_ms) {
        std::string prod_str = encode_productions(state);
        std::string init_state = encode_state(state);

        for (auto& bot : bots) {
            // Send player ID
            bot->write_to_bot(std::to_string(bot->player_id) + "\n");
            // Send map dimensions
            bot->write_to_bot(std::to_string(width) + " " + std::to_string(height) + "\n");
            // Send productions
            bot->write_to_bot(prod_str + "\n");
        }

        if (!quiet) {
            for (auto& bot : bots) {
                std::cout << "Init Message sent to player " << bot->player_id << "." << std::endl;
            }
        }

        // Read bot names
        for (auto& bot : bots) {
            std::string log_section = " --- Init ---\n";

            // Drain any stderr
            bot->drain_stderr();
            if (!bot->log_buffer.empty()) {
                log_section += bot->log_buffer;
                bot->log_buffer.clear();
            }

            auto start = std::chrono::steady_clock::now();
            std::string name = bot->read_line(ignore_timeout ? 99999 : timeout_ms, ignore_timeout);
            auto elapsed = std::chrono::duration_cast<std::chrono::milliseconds>(
                std::chrono::steady_clock::now() - start).count();

            bot->drain_stderr();
            log_section += bot->log_buffer;
            bot->log_buffer.clear();

            log_section += " --- Bot used " + std::to_string(elapsed) + " milliseconds ---\n";

            if (!bot->errored) {
                bot->name = name;
                bot->last_response = name;
                if (!quiet) {
                    std::cout << "Init Message received from player " << bot->player_id 
                              << ", " << bot->name << "." << std::endl;
                }
            } else {
                bot->name = "";
                if (!quiet) {
                    std::cout << "Init Message received from player " << bot->player_id 
                              << ", " << bot->name << "." << std::endl;
                }
            }

            bot->log_buffer = log_section;
        }
    }

    // Parse moves from string
    std::vector<std::vector<int>> parse_moves(const std::string& s) {
        std::vector<std::vector<int>> moves(height, std::vector<int>(width, STILL));
        if (s.empty()) return moves;

        std::istringstream iss(s);
        int x, y, d;
        while (iss >> x >> y >> d) {
            if (x >= 0 && x < width && y >= 0 && y < height && d >= 0 && d <= 4) {
                moves[y][x] = d;
            }
        }
        return moves;
    }

    // Execute a game step
    void execute_moves(const std::vector<std::vector<std::vector<int>>>& player_moves) {
        // Determine which cells are moving
        std::vector<std::vector<bool>> is_moving(height, std::vector<bool>(width, false));
        for (int p = 0; p < num_players; p++) {
            auto& mv = player_moves[p];
            for (int y = 0; y < height; y++) {
                for (int x = 0; x < width; x++) {
                    if (state.grid[y][x].owner == p+1 && mv[y][x] != STILL) {
                        is_moving[y][x] = true;
                    }
                }
            }
        }

        // New grid starts as copy
        GameState new_state = state;

        // Process moves: for each moving cell, transfer strength to target
        // Collect all attacks on each target cell
        std::map<std::pair<int,int>, std::vector<std::pair<int,int>>> attacks;
        // attacks[{tx,ty}] = list of {owner, strength} attacking

        for (int y = 0; y < height; y++) {
            for (int x = 0; x < width; x++) {
                if (!is_moving[y][x]) continue;
                int owner = state.grid[y][x].owner;
                if (owner == 0) continue;

                // Find which player's moves to use
                int p = owner - 1;
                int d = player_moves[p][y][x];

                int nx = (x + DX[d] + width) % width;
                int ny = (y + DY[d] + height) % height;

                attacks[{nx, ny}].emplace_back(owner, state.grid[y][x].strength);

                // Source cell becomes strength 0 (but stays owned)
                new_state.grid[y][x].strength = 0;
            }
        }

        // Resolve attacks
        for (auto& [pos, attackers] : attacks) {
            auto [tx, ty] = pos;
            int target_owner = state.grid[ty][tx].owner;
            int target_str = state.grid[ty][tx].strength;

            // Group by owner
            std::map<int, int> owner_strength;
            for (auto [o, s] : attackers) {
                owner_strength[o] += s;
            }

            if (owner_strength.size() == 1) {
                // Single attacker
                int attacker_owner = owner_strength.begin()->first;
                int attacker_str = owner_strength.begin()->second;

                if (target_owner == attacker_owner) {
                    // Moving into own territory: merge strengths
                    int new_str = std::min(MAX_STRENGTH, new_state.grid[ty][tx].strength + attacker_str);
                    new_state.grid[ty][tx].strength = new_str;
                } else {
                    // Combat
                    if (attacker_str > target_str) {
                        // Attacker wins
                        new_state.grid[ty][tx].owner = attacker_owner;
                        new_state.grid[ty][tx].strength = attacker_str - target_str;
                    } else {
                        // Defender wins (or tie: both destroyed for neutral, attacker loses for player)
                        if (target_owner == 0) {
                            // Neutral cell defends: strength reduced
                            new_state.grid[ty][tx].strength = target_str - attacker_str;
                        } else {
                            // Enemy cell defends
                            new_state.grid[ty][tx].strength = target_str - attacker_str;
                        }
                        // Attacker cell (source) stays at 0 (already set)
                    }
                }
            } else {
                // Multiple attackers - complex resolution
                // In Halite I, when multiple players attack the same cell,
                // each pair fights and the winner fights next
                // OR: all attacking cells reduce each other
                // For simplicity, handle the case where 2 player cells collide:

                // For cells of the SAME player colliding: sum up
                // For cells of DIFFERENT players colliding: mutual combat

                int strongest_owner = -1;
                int strongest_str = 0;
                int total_vs_neutral = 0;

                // Fight among attackers first (mutual damage)
                // Then fight the target

                // Simple approach: total strength of attackers vs target
                // Same player cells merge; different player cells cancel each other

                if (owner_strength.size() == 2) {
                    // Two different players attacking same cell
                    auto it1 = owner_strength.begin();
                    auto it2 = std::next(it1);

                    int o1 = it1->first, s1 = it1->second;
                    int o2 = it2->first, s2 = it2->second;

                    if (s1 > s2) {
                        // o1 wins, with reduced strength
                        int net = s1 - s2;
                        if (target_owner == o1) {
                            new_state.grid[ty][tx].strength = std::min(MAX_STRENGTH, new_state.grid[ty][tx].strength + net);
                        } else if (net > target_str) {
                            new_state.grid[ty][tx].owner = o1;
                            new_state.grid[ty][tx].strength = net - target_str;
                        } else {
                            if (target_owner == 0) {
                                new_state.grid[ty][tx].strength = target_str - net;
                            } else {
                                new_state.grid[ty][tx].strength = target_str - net;
                            }
                        }
                    } else if (s2 > s1) {
                        int net = s2 - s1;
                        if (target_owner == o2) {
                            new_state.grid[ty][tx].strength = std::min(MAX_STRENGTH, new_state.grid[ty][tx].strength + net);
                        } else if (net > target_str) {
                            new_state.grid[ty][tx].owner = o2;
                            new_state.grid[ty][tx].strength = net - target_str;
                        } else {
                            if (target_owner == 0) {
                                new_state.grid[ty][tx].strength = target_str - net;
                            } else {
                                new_state.grid[ty][tx].strength = target_str - net;
                            }
                        }
                    } else {
                        // Both attackers cancel out; target survives (if not neutral, also damaged by s1)
                        if (target_owner == 0) {
                            // Neutral survives as is? Or destroyed?
                            new_state.grid[ty][tx].strength = target_str; // unchanged
                        } else {
                            new_state.grid[ty][tx].strength = target_str;
                        }
                    }
                } else {
                    // More than 2 players - simplified
                    // All attacking strengths fight each other
                    int total_attack = 0;
                    for (auto& [o, s] : owner_strength) total_attack += s;
                    // Apply net damage vs target
                    if (total_attack > target_str) {
                        // This is a simplification; real Halite I has complex rules
                        // Just let the strongest attacker win
                        strongest_owner = -1;
                        for (auto& [o, s] : owner_strength) {
                            if (s > strongest_str) {
                                strongest_str = s;
                                strongest_owner = o;
                            }
                        }
                        if (target_owner != strongest_owner) {
                            new_state.grid[ty][tx].owner = strongest_owner;
                            new_state.grid[ty][tx].strength = strongest_str - target_str;
                        }
                    }
                }
            }
        }

        // Apply production to still cells
        for (int y = 0; y < height; y++) {
            for (int x = 0; x < width; x++) {
                int owner = new_state.grid[y][x].owner;
                if (owner == 0) continue; // neutral cells don't gain production
                if (is_moving[y][x]) continue; // moving cells don't gain production

                // Check if this cell was "attacked" (became a new cell this turn)
                bool was_neutral = (state.grid[y][x].owner == 0);
                bool was_attacked = (attacks.count({x,y}) > 0);

                if (was_neutral || was_attacked) continue; // newly captured cells don't gain production

                int new_str = new_state.grid[y][x].strength + state.productions[y][x];
                new_state.grid[y][x].strength = std::min(MAX_STRENGTH, new_str);
            }
        }

        state = new_state;
    }

    bool is_alive(int player) {
        for (int y = 0; y < height; y++)
            for (int x = 0; x < width; x++)
                if (state.grid[y][x].owner == player) return true;
        return false;
    }

    void record_frame() {
        std::vector<std::vector<std::pair<int,int>>> frame(height);
        for (int y = 0; y < height; y++) {
            frame[y].resize(width);
            for (int x = 0; x < width; x++) {
                frame[y][x] = {state.grid[y][x].owner, state.grid[y][x].strength};
            }
        }
        frames.push_back(frame);
    }

    void run(const std::vector<std::string>& commands, bool quiet_mode, bool noreplay,
             bool ignore_to, bool override_n, const std::string& replay_directory) {
        quiet = quiet_mode;
        ignore_timeout = ignore_to;
        override_names = override_n;
        replay_dir = replay_directory;
        num_players = commands.size();

        // Compute map dimensions
        // (dimensions already set by caller)

        max_turns = compute_max_turns(width, height);

        // Print bot commands
        for (const auto& cmd : commands) {
            std::cout << cmd << std::endl;
            if (!quiet) std::cout << cmd << std::endl; // print twice in non-quiet mode
        }

        // Generate map
        init_game();

        if (!quiet) {
            std::cout << width << " " << height << std::endl;
        } else {
            std::cout << width << " " << height << std::endl;
        }

        // Start bots
        for (int i = 0; i < num_players; i++) {
            bots.push_back(std::make_unique<Bot>(i+1, commands[i]));
            bots.back()->start();
        }

        // Send init
        send_init(ignore_timeout ? 999999 : 15000);

        // Initialize stats
        last_alive_frame.assign(num_players + 1, 0);

        // Record initial frame
        record_frame();

        // Game loop
        int frame_num = 0;
        bool game_over = false;

        std::vector<bool> alive(num_players + 1, true);

        while (frame_num < max_turns && !game_over) {
            frame_num++;

            if (!quiet) {
                std::cout << "Turn " << frame_num << std::endl;
            }

            // Collect moves from all bots
            std::vector<std::vector<std::vector<int>>> player_moves(num_players);

            std::string state_str = encode_state(state);

            // First update alive status and last frames
            for (int p = 1; p <= num_players; p++) {
                if (alive[p] && is_alive(p)) {
                    last_alive_frame[p] = frame_num - 1;
                }
            }

            bool any_alive = false;
            int living_count = 0;
            for (int p = 1; p <= num_players; p++) {
                if (alive[p] && !bots[p-1]->errored) {
                    any_alive = true;
                    living_count++;
                }
            }

            if (living_count <= (num_players > 1 ? 1 : 0)) {
                break;
            }

            for (int p = 0; p < num_players; p++) {
                auto& bot = bots[p];

                std::string log_section = "-----------------------------------------------------------------------------\n";
                log_section += " --- Frame #" + std::to_string(frame_num) + " ---\n";

                if (bot->errored) {
                    player_moves[p] = std::vector<std::vector<int>>(height, std::vector<int>(width, STILL));
                    continue;
                }

                // Send state
                bot->write_to_bot(state_str + "\n");
                bot->drain_stderr();
                log_section += bot->log_buffer;
                bot->log_buffer.clear();

                // Receive moves
                auto start = std::chrono::steady_clock::now();
                std::string response = bot->read_line(ignore_timeout ? 999999 : 1000, ignore_timeout);
                auto elapsed = std::chrono::duration_cast<std::chrono::milliseconds>(
                    std::chrono::steady_clock::now() - start).count();

                bot->drain_stderr();
                log_section += bot->log_buffer;
                bot->log_buffer.clear();

                log_section += " --- Bot used " + std::to_string(elapsed) + " milliseconds ---\n";

                if (bot->errored) {
                    // Bot errored
                    alive[p+1] = false;
                    last_alive_frame[p+1] = frame_num - 1;

                    log_section += "ERRORED!\n";
                    if (response.empty()) {
                        log_section += "No response received.";
                    } else {
                        log_section += "Response received (if any):\n" + response;
                    }

                    // Read any remaining output
                    std::string remaining;
                    char buf[1024];
                    ssize_t n;
                    while ((n = read(bot->stdout_fd, buf, sizeof(buf)-1)) > 0) {
                        buf[n] = 0;
                        remaining += buf;
                    }
                    while ((n = read(bot->stderr_fd, buf, sizeof(buf)-1)) > 0) {
                        buf[n] = 0;
                        remaining += buf;
                    }

                    if (!remaining.empty()) {
                        log_section += "\n --- Bot was killed. Below is the rest of its output (if any): ---\n";
                        log_section += remaining;
                        log_section += "\n --- End bot output ---";
                    }

                    if (!quiet) {
                        std::cerr << "Bot #" << (p+1) << " timeout or error (Unix) 0" << std::endl;
                    }

                    bot->log_buffer = log_section;
                    game_over = true;
                    player_moves[p] = std::vector<std::vector<int>>(height, std::vector<int>(width, STILL));
                } else {
                    bot->last_response = response;
                    player_moves[p] = parse_moves(response);

                    // Log the response
                    log_section += response;
                    bot->log_buffer = log_section;
                }
            }

            if (game_over) break;

            // Store moves for replay
            std::vector<std::vector<int>> combined_moves(height, std::vector<int>(width, STILL));
            for (int p = 0; p < num_players; p++) {
                for (int y = 0; y < height; y++) {
                    for (int x = 0; x < width; x++) {
                        if (state.grid[y][x].owner == p+1) {
                            combined_moves[y][x] = player_moves[p][y][x];
                        }
                    }
                }
            }
            all_moves.push_back(combined_moves);

            // Execute moves
            execute_moves(player_moves);

            // Record frame
            record_frame();

            // Update alive status
            bool any_living = false;
            int alive_count = 0;
            for (int p = 1; p <= num_players; p++) {
                if (alive[p] && !bots[p-1]->errored) {
                    if (is_alive(p)) {
                        last_alive_frame[p] = frame_num;
                        any_living = true;
                        alive_count++;
                    } else {
                        alive[p] = false;
                    }
                }
            }

            if (num_players > 1 && alive_count <= 1) {
                break;
            }
        }

        // Kill all bots
        for (auto& bot : bots) {
            bot->kill_bot();
        }

        // Compute rankings
        // Sort by last_alive_frame (higher = better)
        ranks.assign(num_players + 1, 0);
        std::vector<int> order;
        for (int p = 1; p <= num_players; p++) order.push_back(p);
        std::sort(order.begin(), order.end(), [&](int a, int b) {
            return last_alive_frame[a] < last_alive_frame[b];
        });
        for (int r = 0; r < num_players; r++) {
            ranks[order[r]] = r + 1; // 1=worst, num_players=best
        }

        // Output results
        output_results(noreplay);
    }

