};

// Map dimension adjustment
std::pair<int,int> adjust_dimensions(int w, int h, int n_players) {
    if (n_players == 1) {
        // No adjustment needed for 1 player
        return {w, h};
    }

    // For 2 players: must be even
    if (n_players == 2) {
        // Both must be even
        w = (w / 2) * 2;
        h = (h / 2) * 2;
        return {w, h};
    }

    if (n_players == 3) {
        // Height must be divisible by 3
        h = (h / 3) * 3;
        return {w, h};
    }

    if (n_players == 4) {
        // For 4 players: width/2 must allow symmetric placement
        // The map uses 2x2 grid of quadrants
        // Actually: for 4 players, width must be divisible by 2
        // height must be divisible by 2
        // But empirically we saw width was adjusted differently
        w = (w / 2) * 2;
        h = (h / 2) * 2;
        // But 12x12 with 4 players gave 8x12! 
        // Need to figure out the actual adjustment rule
        // For now, keep w and h even
        return {w, h};
    }

    return {w, h};
}

