        game.run(commands, quietArg.getValue(), noreplayArg.getValue(),
                 timeoutArg.getValue(), overrideArg.getValue(),
                 replayDirArg.getValue());

    } catch (TCLAP::ArgException& e) {
        std::cerr << "error: " << e.error() << " for arg " << e.argId() << std::endl;
        return 1;
    }

    return 0;
}
