#!/usr/bin/env python3
"""Halite I Game Environment - Python Implementation"""

import sys
import os
import json
import math
import time
import select
import fcntl
import subprocess
import signal
import argparse

VERSION = 11
MAX_STRENGTH = 255
STILL, NORTH, EAST, SOUTH, WEST = 0, 1, 2, 3, 4
DX = [0, 0, 1, 0, -1]
DY = [0, -1, 0, 1, 0]

# ============================
# MAP GENERATION
# ============================

class MapGenerator:
    def __init__(self, width, height, num_players, seed):
        self.width = width
        self.height = height
        self.num_players = num_players
        self.seed = seed
        # Use mt19937-compatible seeding via Python's random
        import random
        self.rng = random.Random(seed)

        if num_players > 1:
            self.sym_type = self.rng.randint(0, 3)
        else:
            self.sym_type = -1

    def _smooth_field(self, w, h):
        # Generate raw normal values using Box-Muller (similar to C++ normal_distribution)
        import math
        raw = [[0.0]*w for _ in range(h)]
        for y in range(h):
            for x in range(w):
                # Use rng to generate normal samples
                while True:
                    u = self.rng.random()
                    v = self.rng.random()
                    if u > 0:
                        break
                raw[y][x] = math.sqrt(-2*math.log(u)) * math.cos(2*math.pi*v)

        # Gaussian blur
        area = w * h
        sigma = math.sqrt(area) / 4.0
        if sigma < 1.0:
            sigma = 1.0
        radius = min(int(math.ceil(2*sigma)), min(w,h)//2)

        blurred = [[0.0]*w for _ in range(h)]
        for y in range(h):
            for x in range(w):
                s = 0.0
                sw = 0.0
                for dy in range(-radius, radius+1):
                    for dx in range(-radius, radius+1):
                        k = math.exp(-0.5*(dx*dx+dy*dy)/(sigma*sigma))
                        ny = (y+dy)%h
                        nx = (x+dx)%w
                        s += k * raw[ny][nx]
                        sw += k
                blurred[y][x] = s/sw
        return blurred

    def _apply_symmetry(self, field):
        w, h = self.width, self.height
        if self.sym_type == 0:  # vert flip
            for y in range(h//2):
                for x in range(w):
                    field[h-1-y][x] = field[y][x]
        elif self.sym_type == 1:  # horiz flip
            for y in range(h):
                for x in range(w//2):
                    field[y][w-1-x] = field[y][x]
        elif self.sym_type == 2:  # half-y+x-flip
            for y in range(h):
                for x in range(w):
                    field[(y+h//2)%h][w-1-x] = field[y][x]
        elif self.sym_type == 3:  # half-x+y-flip
            for y in range(h):
                for x in range(w):
                    field[h-1-y][(x+w//2)%w] = field[y][x]

    def generate_productions(self):
        w, h = self.width, self.height
        field = self._smooth_field(w, h)
        if self.num_players > 1:
            self._apply_symmetry(field)

        vals = [field[y][x] for y in range(h) for x in range(w)]
        mn, mx = min(vals), max(vals)
        if mx == mn:
            return [[0]*w for _ in range(h)]
        return [[round((field[y][x]-mn)/(mx-mn)*15) for x in range(w)] for y in range(h)]

    def generate_strengths(self):
        w, h = self.width, self.height
        field = self._smooth_field(w, h)
        if self.num_players > 1:
            self._apply_symmetry(field)

        vals = [field[y][x] for y in range(h) for x in range(w)]
        mn, mx = min(vals), max(vals)
        if mx == mn:
            return [[128]*w for _ in range(h)]
        return [[round((field[y][x]-mn)/(mx-mn)*255) for x in range(w)] for y in range(h)]

    def get_starting_positions(self):
        n = self.num_players
        w, h = self.width, self.height

        if n == 1:
            return [(w//2, h//2)]

        if self.sym_type == 0:  # vert flip
            x1 = w//2
            y1 = h//(2*n)
            return [(x1, y1), (x1, h-1-y1)][:n]
        elif self.sym_type == 1:  # horiz flip
            x1 = w//(2*n)
            y1 = h//2
            return [(x1, y1), (w-1-x1, y1)][:n]
        elif self.sym_type == 2:  # half-y+x-flip
            x1 = w//(2*n)
            y1 = h//2
            return [(x1, y1), (w-1-x1, (y1+h//2)%h)][:n]
        elif self.sym_type == 3:  # half-x+y-flip
            x1 = w//2
            y1 = h//(2*n)
            return [(x1, y1), ((x1+w//2)%w, h-1-y1)][:n]

        return [(w//2, h//2)] * n

    def generate(self):
        prods = self.generate_productions()
        strs = self.generate_strengths()

        grid = [[{'owner': 0, 'strength': strs[y][x]}
                 for x in range(self.width)] for y in range(self.height)]

        positions = self.get_starting_positions()
        for p, (px, py) in enumerate(positions):
            grid[py][px]['owner'] = p+1

        return {'width': self.width, 'height': self.height,
                'productions': prods, 'grid': grid}


def adjust_dimensions(w, h, n):
    if n <= 1:
        return w, h
    elif n == 2:
        return (w//2)*2, (h//2)*2
    elif n == 3:
        return w, (h//3)*3
    elif n == 4:
        return (w//4)*4, (h//2)*2
    elif n == 5:
        return w, (h//5)*5
    elif n == 6:
        return (w//3)*3, (h//2)*2
    return w, h


# ============================
