def encode_state(grid, w, h):
    owners = [grid[y][x]['owner'] for y in range(h) for x in range(w)]
    runs = []
    cur = owners[0]; count = 1
    for o in owners[1:]:
        if o == cur: count += 1
        else:
            runs.append(f"{count} {cur}")
            cur = o; count = 1
    runs.append(f"{count} {cur}")
    strs = ' '.join(str(grid[y][x]['strength']) for y in range(h) for x in range(w))
    return ' '.join(runs) + ' ' + strs


def encode_productions(prods, w, h):
    return ' '.join(str(prods[y][x]) for y in range(h) for x in range(w))


def parse_moves(response, w, h):
    moves = [[STILL]*w for _ in range(h)]
    if not response: return moves
    parts = response.split()
    i = 0
    while i+2 < len(parts):
        try:
            x, y, d = int(parts[i]), int(parts[i+1]), int(parts[i+2])
            if 0<=x<w and 0<=y<h and 0<=d<=4:
                moves[y][x] = d
            i += 3
        except:
            i += 1
    return moves


def execute_frame(grid, prods, all_moves, w, h):
    """Execute one game turn"""
    n = len(all_moves)

    # Determine which player-owned cells are moving
    is_moving = [[False]*w for _ in range(h)]
    for y in range(h):
        for x in range(w):
            owner = grid[y][x]['owner']
            if owner == 0: continue
            p_idx = owner - 1
            if p_idx < n and all_moves[p_idx][y][x] != STILL:
                is_moving[y][x] = True

    new_grid = [[dict(grid[y][x]) for x in range(w)] for y in range(h)]

    # Collect attacks
    attacks = {}  # (tx,ty) -> list of (owner, str)
    for y in range(h):
        for x in range(w):
            if not is_moving[y][x]: continue
            owner = grid[y][x]['owner']
            if owner == 0: continue
            d = all_moves[owner-1][y][x]
            nx = (x+DX[d]+w)%w
            ny = (y+DY[d]+h)%h
            key = (nx, ny)
            if key not in attacks: attacks[key] = []
            attacks[key].append((owner, grid[y][x]['strength']))
            new_grid[y][x]['strength'] = 0

    # Resolve attacks
    for (tx,ty), atts in attacks.items():
        tgt_owner = grid[ty][tx]['owner']
        tgt_str = grid[ty][tx]['strength']

        owner_str = {}
        for o, s in atts:
            owner_str[o] = owner_str.get(o, 0) + s

        if len(owner_str) == 1:
            ao, astr = list(owner_str.items())[0]
            if ao == tgt_owner:
                new_grid[ty][tx]['strength'] = min(MAX_STRENGTH,
                    new_grid[ty][tx]['strength'] + astr)
            else:
                if astr > tgt_str:
                    new_grid[ty][tx]['owner'] = ao
                    new_grid[ty][tx]['strength'] = astr - tgt_str
                else:
                    new_grid[ty][tx]['strength'] = tgt_str - astr
        else:
            owners_list = sorted(owner_str.items(), key=lambda x: -x[1])
            net = owners_list[0][1]
            for _, s in owners_list[1:]:
                net -= s
            if net > 0:
                ao = owners_list[0][0]
                if ao == tgt_owner:
                    new_grid[ty][tx]['strength'] = min(MAX_STRENGTH,
                        new_grid[ty][tx]['strength'] + net)
                elif net > tgt_str:
                    new_grid[ty][tx]['owner'] = ao
                    new_grid[ty][tx]['strength'] = net - tgt_str
                else:
                    new_grid[ty][tx]['strength'] = tgt_str - net

    # Add production to still cells
    attacked_cells = set(attacks.keys())
    for y in range(h):
        for x in range(w):
            owner = new_grid[y][x]['owner']
            if owner == 0: continue
            if is_moving[y][x]: continue
            if (x,y) in attacked_cells: continue
            if grid[y][x]['owner'] == 0: continue  # was neutral
            new_str = new_grid[y][x]['strength'] + prods[y][x]
            new_grid[y][x]['strength'] = min(MAX_STRENGTH, new_str)

    return new_grid


def is_alive(grid, player, w, h):
    return any(grid[y][x]['owner'] == player for y in range(h) for x in range(w))


