#!/usr/bin/env python3
"""Halite I Game Environment - Python Implementation"""

import sys
import os
import json
import math
import time
import select
import fcntl
import subprocess
import signal
import argparse

VERSION = 11
MAX_STRENGTH = 255
STILL, NORTH, EAST, SOUTH, WEST = 0, 1, 2, 3, 4
DX = [0, 0, 1, 0, -1]
DY = [0, -1, 0, 1, 0]

# ============================
# MAP GENERATION
# ============================

class MapGenerator:
    def __init__(self, width, height, num_players, seed):
        self.width = width
        self.height = height
        self.num_players = num_players
        self.seed = seed
        # Use mt19937-compatible seeding via Python's random
        import random
        self.rng = random.Random(seed)

        if num_players > 1:
            self.sym_type = self.rng.randint(0, 3)
        else:
            self.sym_type = -1

    def _smooth_field(self, w, h):
        # Generate raw normal values using Box-Muller (similar to C++ normal_distribution)
        import math
        raw = [[0.0]*w for _ in range(h)]
        for y in range(h):
            for x in range(w):
                # Use rng to generate normal samples
                while True:
                    u = self.rng.random()
                    v = self.rng.random()
                    if u > 0:
                        break
                raw[y][x] = math.sqrt(-2*math.log(u)) * math.cos(2*math.pi*v)

        # Gaussian blur
        area = w * h
        sigma = math.sqrt(area) / 4.0
        if sigma < 1.0:
            sigma = 1.0
        radius = min(int(math.ceil(2*sigma)), min(w,h)//2)

        blurred = [[0.0]*w for _ in range(h)]
        for y in range(h):
            for x in range(w):
                s = 0.0
                sw = 0.0
                for dy in range(-radius, radius+1):
                    for dx in range(-radius, radius+1):
                        k = math.exp(-0.5*(dx*dx+dy*dy)/(sigma*sigma))
                        ny = (y+dy)%h
                        nx = (x+dx)%w
                        s += k * raw[ny][nx]
                        sw += k
                blurred[y][x] = s/sw
        return blurred

    def _apply_symmetry(self, field):
        w, h = self.width, self.height
        if self.sym_type == 0:  # vert flip
            for y in range(h//2):
                for x in range(w):
                    field[h-1-y][x] = field[y][x]
        elif self.sym_type == 1:  # horiz flip
            for y in range(h):
                for x in range(w//2):
                    field[y][w-1-x] = field[y][x]
        elif self.sym_type == 2:  # half-y+x-flip
            for y in range(h):
                for x in range(w):
                    field[(y+h//2)%h][w-1-x] = field[y][x]
        elif self.sym_type == 3:  # half-x+y-flip
            for y in range(h):
                for x in range(w):
                    field[h-1-y][(x+w//2)%w] = field[y][x]

    def generate_productions(self):
        w, h = self.width, self.height
        field = self._smooth_field(w, h)
        if self.num_players > 1:
            self._apply_symmetry(field)

        vals = [field[y][x] for y in range(h) for x in range(w)]
        mn, mx = min(vals), max(vals)
        if mx == mn:
            return [[0]*w for _ in range(h)]
        return [[round((field[y][x]-mn)/(mx-mn)*15) for x in range(w)] for y in range(h)]

    def generate_strengths(self):
        w, h = self.width, self.height
        field = self._smooth_field(w, h)
        if self.num_players > 1:
            self._apply_symmetry(field)

        vals = [field[y][x] for y in range(h) for x in range(w)]
        mn, mx = min(vals), max(vals)
        if mx == mn:
            return [[128]*w for _ in range(h)]
        return [[round((field[y][x]-mn)/(mx-mn)*255) for x in range(w)] for y in range(h)]

    def get_starting_positions(self):
        n = self.num_players
        w, h = self.width, self.height

        if n == 1:
            return [(w//2, h//2)]

        if self.sym_type == 0:  # vert flip
            x1 = w//2
            y1 = h//(2*n)
            return [(x1, y1), (x1, h-1-y1)][:n]
        elif self.sym_type == 1:  # horiz flip
            x1 = w//(2*n)
            y1 = h//2
            return [(x1, y1), (w-1-x1, y1)][:n]
        elif self.sym_type == 2:  # half-y+x-flip
            x1 = w//(2*n)
            y1 = h//2
            return [(x1, y1), (w-1-x1, (y1+h//2)%h)][:n]
        elif self.sym_type == 3:  # half-x+y-flip
            x1 = w//2
            y1 = h//(2*n)
            return [(x1, y1), ((x1+w//2)%w, h-1-y1)][:n]

        return [(w//2, h//2)] * n

    def generate(self):
        prods = self.generate_productions()
        strs = self.generate_strengths()

        grid = [[{'owner': 0, 'strength': strs[y][x]}
                 for x in range(self.width)] for y in range(self.height)]

        positions = self.get_starting_positions()
        for p, (px, py) in enumerate(positions):
            grid[py][px]['owner'] = p+1

        return {'width': self.width, 'height': self.height,
                'productions': prods, 'grid': grid}


def adjust_dimensions(w, h, n):
    if n <= 1:
        return w, h
    elif n == 2:
        return (w//2)*2, (h//2)*2
    elif n == 3:
        return w, (h//3)*3
    elif n == 4:
        return (w//4)*4, (h//2)*2
    elif n == 5:
        return w, (h//5)*5
    elif n == 6:
        return (w//3)*3, (h//2)*2
    return w, h


# ============================
# GAME LOGIC
# ============================

def encode_state(grid, w, h):
    owners = [grid[y][x]['owner'] for y in range(h) for x in range(w)]
    runs = []
    cur = owners[0]; count = 1
    for o in owners[1:]:
        if o == cur: count += 1
        else:
            runs.append(f"{count} {cur}")
            cur = o; count = 1
    runs.append(f"{count} {cur}")
    strs = ' '.join(str(grid[y][x]['strength']) for y in range(h) for x in range(w))
    return ' '.join(runs) + ' ' + strs


def encode_productions(prods, w, h):
    return ' '.join(str(prods[y][x]) for y in range(h) for x in range(w))


def parse_moves(response, w, h):
    moves = [[STILL]*w for _ in range(h)]
    if not response: return moves
    parts = response.split()
    i = 0
    while i+2 < len(parts):
        try:
            x, y, d = int(parts[i]), int(parts[i+1]), int(parts[i+2])
            if 0<=x<w and 0<=y<h and 0<=d<=4:
                moves[y][x] = d
            i += 3
        except:
            i += 1
    return moves


def execute_frame(grid, prods, all_moves, w, h):
    """Execute one game turn"""
    n = len(all_moves)

    # Determine which player-owned cells are moving
    is_moving = [[False]*w for _ in range(h)]
    for y in range(h):
        for x in range(w):
            owner = grid[y][x]['owner']
            if owner == 0: continue
            p_idx = owner - 1
            if p_idx < n and all_moves[p_idx][y][x] != STILL:
                is_moving[y][x] = True

    new_grid = [[dict(grid[y][x]) for x in range(w)] for y in range(h)]

    # Collect attacks
    attacks = {}  # (tx,ty) -> list of (owner, str)
    for y in range(h):
        for x in range(w):
            if not is_moving[y][x]: continue
            owner = grid[y][x]['owner']
            if owner == 0: continue
            d = all_moves[owner-1][y][x]
            nx = (x+DX[d]+w)%w
            ny = (y+DY[d]+h)%h
            key = (nx, ny)
            if key not in attacks: attacks[key] = []
            attacks[key].append((owner, grid[y][x]['strength']))
            new_grid[y][x]['strength'] = 0

    # Resolve attacks
    for (tx,ty), atts in attacks.items():
        tgt_owner = grid[ty][tx]['owner']
        tgt_str = grid[ty][tx]['strength']

        owner_str = {}
        for o, s in atts:
            owner_str[o] = owner_str.get(o, 0) + s

        if len(owner_str) == 1:
            ao, astr = list(owner_str.items())[0]
            if ao == tgt_owner:
                new_grid[ty][tx]['strength'] = min(MAX_STRENGTH,
                    new_grid[ty][tx]['strength'] + astr)
            else:
                if astr > tgt_str:
                    new_grid[ty][tx]['owner'] = ao
                    new_grid[ty][tx]['strength'] = astr - tgt_str
                else:
                    new_grid[ty][tx]['strength'] = tgt_str - astr
        else:
            owners_list = sorted(owner_str.items(), key=lambda x: -x[1])
            net = owners_list[0][1]
            for _, s in owners_list[1:]:
                net -= s
            if net > 0:
                ao = owners_list[0][0]
                if ao == tgt_owner:
                    new_grid[ty][tx]['strength'] = min(MAX_STRENGTH,
                        new_grid[ty][tx]['strength'] + net)
                elif net > tgt_str:
                    new_grid[ty][tx]['owner'] = ao
                    new_grid[ty][tx]['strength'] = net - tgt_str
                else:
                    new_grid[ty][tx]['strength'] = tgt_str - net

    # Add production to still cells
    attacked_cells = set(attacks.keys())
    for y in range(h):
        for x in range(w):
            owner = new_grid[y][x]['owner']
            if owner == 0: continue
            if is_moving[y][x]: continue
            if (x,y) in attacked_cells: continue
            if grid[y][x]['owner'] == 0: continue  # was neutral
            new_str = new_grid[y][x]['strength'] + prods[y][x]
            new_grid[y][x]['strength'] = min(MAX_STRENGTH, new_str)

    return new_grid


def is_alive(grid, player, w, h):
    return any(grid[y][x]['owner'] == player for y in range(h) for x in range(w))


# ============================
# BOT MANAGEMENT
# ============================

class Bot:
    def __init__(self, pid, cmd):
        self.player_id = pid
        self.cmd = cmd
        self.name = ""
        self.proc = None
        self.stdin_fd = -1
        self.stdout_fd = -1
        self.stderr_fd = -1
        self.errored = False
        self.log = ""
        self.last_response = ""

    def start(self):
        self.proc = subprocess.Popen(
            self.cmd, shell=True,
            stdin=subprocess.PIPE,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE
        )
        self.stdin_fd = self.proc.stdin.fileno()
        self.stdout_fd = self.proc.stdout.fileno()
        self.stderr_fd = self.proc.stderr.fileno()

        # Set stdout/stderr to non-blocking
        for fd in [self.stdout_fd, self.stderr_fd]:
            fl = fcntl.fcntl(fd, fcntl.F_GETFL)
            fcntl.fcntl(fd, fcntl.F_SETFL, fl | os.O_NONBLOCK)

    def write(self, s):
        try:
            data = (s + '\n').encode()
            total = len(data)
            sent = 0
            while sent < total:
                n = os.write(self.stdin_fd, data[sent:])
                sent += n
        except Exception:
            self.errored = True

    def read_line(self, timeout_ms=15000, ignore_timeout=False):
        if self.errored: return ""

        deadline = time.time() + timeout_ms/1000.0
        line = b''

        while True:
            if not ignore_timeout and time.time() > deadline:
                self.errored = True
                return ""

            remaining = (deadline - time.time()) if not ignore_timeout else 1.0
            try:
                ready = select.select([self.stdout_fd], [], [], max(0.001, remaining))
            except Exception:
                self.errored = True
                return ""

            if not ready[0]:
                if not ignore_timeout:
                    self.errored = True
                    return ""
                continue

            try:
                c = os.read(self.stdout_fd, 1)
            except Exception:
                self.errored = True
                return ""

            if not c:
                self.errored = True
                return ""

            if c == b'\n':
                return line.decode('utf-8', errors='replace').rstrip('\r')
            line += c

    def drain_stderr(self):
        while True:
            try:
                ready = select.select([self.stderr_fd], [], [], 0)
            except Exception:
                break
            if not ready[0]:
                break
            try:
                data = os.read(self.stderr_fd, 4096)
                if not data:
                    break
                self.log += data.decode('utf-8', errors='replace')
            except Exception:
                break

    def read_remaining(self):
        result = ""
        for fd in [self.stdout_fd, self.stderr_fd]:
            try:
                fl = fcntl.fcntl(fd, fcntl.F_GETFL)
                fcntl.fcntl(fd, fcntl.F_SETFL, fl | os.O_NONBLOCK)
                while True:
                    data = os.read(fd, 4096)
                    if not data: break
                    result += data.decode('utf-8', errors='replace')
            except:
                pass
        return result

    def kill(self):
        if self.proc:
            try:
                self.proc.kill()
                self.proc.wait(timeout=1)
            except:
                pass
            try:
                for fd in [self.stdin_fd, self.stdout_fd, self.stderr_fd]:
                    if fd >= 0:
                        try: os.close(fd)
                        except: pass
            except:
                pass
            self.proc = None


# ============================
# GAME RUNNER
# ============================

def compute_max_turns(w, h):
    return int(10 * math.sqrt(w*h))


def run_game(commands, seed, width, height, quiet, noreplay,
             ignore_timeout, override_names, replay_dir):

    n = len(commands)
    max_turns = compute_max_turns(width, height)

    # Print commands
    for cmd in commands:
        print(cmd)
        if not quiet:
            print(cmd)

    # Generate map
    gen = MapGenerator(width, height, n, seed)
    game_state = gen.generate()
    grid = game_state['grid']
    prods = game_state['productions']

    print(f"{width} {height}")

    # Start bots
    bots = [Bot(i+1, cmd) for i, cmd in enumerate(commands)]
    for bot in bots:
        bot.start()

    # Send init to all bots
    prod_str = encode_productions(prods, width, height)
    for bot in bots:
        bot.write(str(bot.player_id))
        bot.write(f"{width} {height}")
        bot.write(prod_str)

    if not quiet:
        for bot in bots:
            print(f"Init Message sent to player {bot.player_id}.")

    # Receive names
    for bot in bots:
        log = " --- Init ---\n"
        bot.drain_stderr()
        log += bot.log; bot.log = ""

        t0 = time.time()
        name = bot.read_line(99999 if ignore_timeout else 15000, ignore_timeout)
        elapsed = int((time.time()-t0)*1000)

        bot.drain_stderr()
        log += bot.log; bot.log = ""
        log += f" --- Bot used {elapsed} milliseconds ---\n"

        if not bot.errored:
            bot.name = bot.cmd if override_names else name
            if not quiet:
                print(f"Init Message received from player {bot.player_id}, {bot.name}.")
        else:
            bot.name = ""
            if not quiet:
                print(f"Init Message received from player {bot.player_id}, {bot.name}.")

        bot.log = log

    # Game loop
    last_frame = {bot.player_id: 0 for bot in bots}
    alive = {bot.player_id: True for bot in bots}

    frames = []  # [(owner, str) for each cell] as list of lists
    all_moves_list = []

    def snapshot():
        return [[(grid[y][x]['owner'], grid[y][x]['strength'])
                 for x in range(width)] for y in range(height)]

    frames.append(snapshot())

    # Update initial last_frame
    for bot in bots:
        if is_alive(grid, bot.player_id, width, height):
            last_frame[bot.player_id] = 0

    game_over = False
    frame_num = 0

    while frame_num < max_turns and not game_over:
        frame_num += 1

        if not quiet:
            print(f"Turn {frame_num}")

        # Check alive count
        living = [b for b in bots if alive[b.player_id] and not b.errored]
        if n > 1 and len(living) <= 1:
            break

        state_str = encode_state(grid, width, height)
        moves_by_player = []

        for bot in bots:
            log = "-----------------------------------------------------------------------------\n"
            log += f" --- Frame #{frame_num} ---\n"

            if bot.errored:
                moves_by_player.append([[STILL]*width for _ in range(height)])
                continue

            bot.write(state_str)
            bot.drain_stderr()
            log += bot.log; bot.log = ""

            t0 = time.time()
            resp = bot.read_line(99999 if ignore_timeout else 1000, ignore_timeout)
            elapsed = int((time.time()-t0)*1000)

            bot.drain_stderr()
            log += bot.log; bot.log = ""
            log += f" --- Bot used {elapsed} milliseconds ---\n"

            if bot.errored:
                alive[bot.player_id] = False
                log += "ERRORED!\n"

                remaining = bot.read_remaining()

                if resp:
                    log += f"Response received (if any):\n{resp}"
                else:
                    log += "No response received."

                if remaining:
                    log += f"\n --- Bot was killed. Below is the rest of its output (if any): ---\n"
                    log += remaining
                    log += "\n --- End bot output ---"

                bot.log = log
                bot.kill()

                if not quiet:
                    print(f"Bot #{bot.player_id} timeout or error (Unix) 0", file=sys.stderr)

                game_over = True
                moves_by_player.append([[STILL]*width for _ in range(height)])
            else:
                bot.last_response = resp
                log += resp if resp else ""
                bot.log = log
                moves_by_player.append(parse_moves(resp, width, height))

        if game_over:
            break

        # Record combined moves
        combined = [[STILL]*width for _ in range(height)]
        for p_idx, bot in enumerate(bots):
            for y in range(height):
                for x in range(width):
                    if grid[y][x]['owner'] == bot.player_id:
                        combined[y][x] = moves_by_player[p_idx][y][x]
        all_moves_list.append(combined)

        # Execute frame
        grid = execute_frame(grid, prods, moves_by_player, width, height)
        frames.append(snapshot())

        # Update alive
        for bot in bots:
            if alive[bot.player_id] and not bot.errored:
                if is_alive(grid, bot.player_id, width, height):
                    last_frame[bot.player_id] = frame_num
                else:
                    alive[bot.player_id] = False

        living = [b for b in bots if alive[b.player_id] and not b.errored]
        if n > 1 and len(living) <= 1:
            break

    # Kill all bots
    for bot in bots:
        bot.kill()

    # Compute rankings
    sorted_bots = sorted(bots, key=lambda b: last_frame[b.player_id])
    ranks = {bot.player_id: i+1 for i, bot in enumerate(sorted_bots)}  # 1=worst

    # Write log files for errored bots
    ts = int(time.time())
    log_files = {}
    for bot in bots:
        if bot.errored:
            lf = f"{bot.player_id}-{ts}.log"
            with open(lf, 'w') as f:
                f.write(bot.log)
            log_files[bot.player_id] = lf

    # Save replay
    replay_path = None
    if not noreplay:
        rdir = replay_dir if replay_dir and replay_dir != '.' else '.'
        replay_path = f"{rdir}/{ts}-{seed}.hlt"

        j = {
            "version": VERSION,
            "width": width,
            "height": height,
            "num_players": n,
            "num_frames": len(frames),
            "player_names": [bot.name for bot in bots],
            "productions": prods,
            "frames": [
                [[[cell[0], cell[1]] for cell in row] for row in frame]
                for frame in frames
            ],
            "moves": [
                [[m[y][x] for x in range(width)] for y in range(height)]
                for m in all_moves_list
            ]
        }
        with open(replay_path, 'w') as f:
            json.dump(j, f, separators=(',', ':'))

    # Output
    if not quiet:
        print(f"Map seed was {seed}")
        if replay_path:
            print(f"Opening a file at {replay_path}")
        sorted_by_rank = sorted(bots, key=lambda b: ranks[b.player_id])
        for bot in sorted_by_rank:
            actual_rank = n - ranks[bot.player_id] + 1
            print(f"Player #{bot.player_id}, {bot.name}, came in rank #{actual_rank} and was last alive on frame #{last_frame[bot.player_id]}!")
    else:
        if replay_path:
            print(f"{replay_path} {seed}")

        sorted_desc = sorted(bots, key=lambda b: -ranks[b.player_id])
        for bot in sorted_desc:
            actual_rank = n - ranks[bot.player_id] + 1
            print(f"{bot.player_id} {actual_rank} {last_frame[bot.player_id]}")

        errored = [b for b in bots if b.errored]
        ids = ' '.join(str(b.player_id) for b in errored)
        logs = ' '.join(log_files.get(b.player_id, '') for b in errored)

        print(f"{ids} ")
        print(f"{logs} ", end='')


def print_help():
    prog = sys.argv[0]
    print(f"""
USAGE: 

   {prog}  [-i <path to directory>] [-s <positive integer>] [-d <a
                 string containing two space-seprated positive integers>]
                 [-n <{{1,2,3,4,5,6}}>] [-r] [-t] [-o] [-q] [--] [--version]
                 [-h] <Array of strings> ...


Where: 

   -i <path to directory>,  --replaydirectory <path to directory>
     The path to directory for replay output.

   -s <positive integer>,  --seed <positive integer>
     The seed for the map generator.

   -d <a string containing two space-seprated positive integers>, 
      --dimensions <a string containing two space-seprated positive
      integers>
     The dimensions of the map.

   -n <{{1,2,3,4,5,6}}>,  --nplayers <{{1,2,3,4,5,6}}>
     Create a map that will accommodate n players [SINGLE PLAYER MODE
     ONLY].

   -r,  --noreplay
     Turns off the replay generation.

   -t,  --timeout
     Causes game environment to ignore timeouts (give all bots infinite
     time).

   -o,  --override
     Overrides player-sent names using cmd args [SERVER ONLY].

   -q,  --quiet
     Runs game in quiet mode, producing machine-parsable output.

   --,  --ignore_rest
     Ignores the rest of the labeled arguments following this flag.

   --version
     Displays version information and exits.

   -h,  --help
     Displays usage information and exits.

   <Array of strings>  (accepted multiple times)
     Start commands for bots.
""")


def main():
    args = sys.argv[1:]

    replay_dir = "."
    seed = int(time.time())
    dims = None
    n_players_arg = -1
    noreplay = False
    ignore_timeout = False
    override_names = False
    quiet = False
    commands = []

    i = 0
    while i < len(args):
        a = args[i]
        if a in ('-i', '--replaydirectory'):
            i += 1
            replay_dir = args[i]
        elif a in ('-s', '--seed'):
            i += 1
            seed = int(args[i])
        elif a in ('-d', '--dimensions'):
            i += 1
            dims = args[i]
        elif a in ('-n', '--nplayers'):
            i += 1
            n_players_arg = int(args[i])
        elif a in ('-r', '--noreplay'):
            noreplay = True
        elif a in ('-t', '--timeout'):
            ignore_timeout = True
        elif a in ('-o', '--override'):
            override_names = True
        elif a in ('-q', '--quiet'):
            quiet = True
        elif a in ('--', '--ignore_rest'):
            i += 1
            commands.extend(args[i:])
            break
        elif a == '--version':
            print(f"\n{sys.argv[0]}  version: 1.2\n")
            return
        elif a in ('-h', '--help'):
            print_help()
            return
        else:
            commands.append(a)
        i += 1

    if not commands:
        print_help()
        return

    n_bots = len(commands)

    if n_players_arg > 1 and n_bots > 1:
        print("\nOnly single-player mode enables specified n-player maps.  When entering multiple bots, please do not try to specify n.\n")
        return

    effective_n = n_bots
    if n_bots == 1 and n_players_arg > 0:
        effective_n = n_players_arg

    if dims:
        parts = dims.split()
        w, h = int(parts[0]), int(parts[1])
    else:
        size = max(20, int(10*math.sqrt(effective_n) + 5))
        w, h = size, size

    w, h = adjust_dimensions(w, h, effective_n)

    run_game(commands, seed, w, h, quiet, noreplay,
             ignore_timeout, override_names, replay_dir)


if __name__ == '__main__':
    main()
