    int expected[] = {35,25,25,35,35,30,30,35,50,25,40,40,25,25,25,30,30,30,30,30};

    // Try: size = 20 + (mt() % N) * 5 for various N and offsets
    for (int base : {20, 25}) {
        for (int N = 4; N <= 8; N++) {
            for (int skip = 0; skip <= 3; skip++) {
                bool all_match = true;
                for (int i = 0; i < 20; i++) {
                    int seed = i+1;
                    mt19937 mt(seed);
                    for (int s = 0; s < skip; s++) mt();
                    int v = mt() % N;
                    int size = base + v * 5;
                    if (size != expected[i]) { all_match = false; break; }
                }
                if (all_match) {
                    printf("MATCH! base=%d N=%d skip=%d\n", base, N, skip);
